    void UpdateWindowTitle()=>Title=Localization.Format("window.title",_dirtyState.IsDirty?"*":"",string.IsNullOrWhiteSpace(_titlePath)?Localization.DisplayText("window.untitled"):System.IO.Path.GetFileName(_titlePath));
    void BendCreated(object? sender,BendObject e){ShowProperties(e);StatusText.Text=Localization.Format("ui.0018", e.Id, e.Layer);RefreshAll();}
    void RefreshAll()
    {
        ApplyRulerGridPreferences();
        WidthBox.Text=_document.Material.Width.ToString("0.###",CultureInfo.CurrentCulture);HeightBox.Text=_document.Material.Height.ToString("0.###",CultureInfo.CurrentCulture);ThicknessBox.Text=_document.Material.Thickness.ToString("0.###",CultureInfo.CurrentCulture);if(WidthBox.Parent is Grid grid&&grid.Parent is GroupBox group)group.Header=Localization.Format("ui.0019", _document.Unit.Symbol());
        ObjectTree.Items.Clear();var material=new TreeViewItem{Header=Localization.Text("ui.0020"),Tag=_document.Material};var outer=new TreeViewItem{Header=Localization.Text("ui.0021"),Tag=_document.OuterContour};var gi=1;foreach(var g in _document.OuterContour.Segments){var go=new GeometryObject{Id=$"L{gi:000}",Sequence=gi,ParentContourId="OUTER",Layer="L",EntityType=g switch{LineSegment=>"LINE",ArcSegment=>"ARC",_=>"CIRCLE"},Geometry=g};outer.Items.Add(new TreeViewItem{Header=Localization.Format("ui.0022", gi, go.EntityType, go.Id),Tag=go});gi++;}material.Items.Add(outer);
        var v=new TreeViewItem{Header=Localization.Format("ui.0023", _document.Bends.Count(x=>x.Layer=="V"))};foreach(var b in _document.Bends.Where(x=>x.Layer=="V").OrderBy(x=>x.Sequence))v.Items.Add(new TreeViewItem{Header=Localization.Format("ui.0024", b.Sequence, b.Id),Tag=b});material.Items.Add(v);
        var v1=new TreeViewItem{Header=Localization.Format("ui.0025", _document.Bends.Count(x=>x.Layer=="V1"))};foreach(var b in _document.Bends.Where(x=>x.Layer=="V1").OrderBy(x=>x.Sequence))v1.Items.Add(new TreeViewItem{Header=Localization.Format("ui.0026", b.Sequence, b.Id),Tag=b});material.Items.Add(v1);
        var sections=new TreeViewItem{Header=Localization.Text("ui.0027")};var ws=new TreeViewItem{Header=Localization.Text("ui.0028")};foreach(var s in _document.WSegments)ws.Items.Add(new TreeViewItem{Header=Localization.Format("ui.0029", s.Id, s.Length, _document.Unit.Symbol()),Tag=s});var hs=new TreeViewItem{Header=Localization.Text("ui.0030")};foreach(var s in _document.HSegments)hs.Items.Add(new TreeViewItem{Header=Localization.Format("ui.0031", s.Id, s.Length, _document.Unit.Symbol()),Tag=s});sections.Items.Add(ws);sections.Items.Add(hs);material.Items.Add(sections);
        var cuts=new TreeViewItem{Header=Localization.Format("ui.0032", _document.Cuts.Count)};foreach(var c in _document.Cuts){var cutItem=new TreeViewItem{Header=Localization.Format("ui.0033", c.Sequence, Localization.DisplayKind(c.Shape), c.Id),Tag=c};for(var ci=0;ci<(c.Shape is "RegularPolygon" or "RegularStar"||EllipsePropertiesEngine.TryGet(c,out _)?0:c.Geometry.Count);ci++){var geometry=c.Geometry[ci];var child=new GeometryObject{Id=$"{c.Id}-L{ci+1:000}",Sequence=ci+1,ParentContourId=c.Id,Layer="L",EntityType=geometry switch{LineSegment=>"LINE",ArcSegment=>"ARC",_=>"CIRCLE"},Geometry=geometry};cutItem.Items.Add(new TreeViewItem{Header=Localization.Format("ui.0034", ci+1, child.EntityType, child.Id),Tag=child});}cuts.Items.Add(cutItem);}material.Items.Add(cuts);cuts.IsExpanded=true;
        var slits=new TreeViewItem{Header=Localization.Format("ui.0035", _document.Slits.Count),IsExpanded=true};foreach(var slit in _document.Slits)slits.Items.Add(new TreeViewItem{Header=Localization.Format("ui.0036", slit.Sequence, Localization.DisplayKind(slit.Shape), slit.Id),Tag=slit});material.Items.Add(slits);
        var joints=new TreeViewItem{Header=Localization.Format("ui.0037", _document.MicroJoints.Count)};foreach(var j in _document.MicroJoints)joints.Items.Add(new TreeViewItem{Header=$"{j.Sequence:000} {j.Id}",Tag=j});material.Items.Add(joints);ObjectTree.Items.Add(material);material.IsExpanded=true;outer.IsExpanded=true;v.IsExpanded=true;v1.IsExpanded=true;
        if(FlatView.SelectedObject is { } selected)SelectTreeObject(selected.Id);FlatView.Refresh();WSection.Refresh();HSection.Refresh();Preview3D.Refresh();
    }
    void New_Click(object sender,RoutedEventArgs e){if(!ConfirmSaveChanges())return;_path=null;_titlePath=null;_history.Clear();var document=new VCuttingDocument();document.ConfigureNew(_settings.NewWidth,_settings.NewHeight,_settings.NewThickness,_settings.DefaultUnit);ApplySectionDefaults(document);Attach(document);_dirtyState.MarkSaved();UpdateWindowTitle();StatusText.Text=Localization.Text("ui.0038");}
    void Open_Click(object sender,RoutedEventArgs e){if(!ConfirmSaveChanges())return;var d=new OpenFileDialog{Filter=Localization.DxfFilter,InitialDirectory=ValidFolder(_settings.DefaultOpenFolder)};if(d.ShowDialog()==true)OpenPath(d.FileName);}
    void OpenPath(string fileName){try{VCuttingDocument opened;string status;var plainImport=false;if(VCuttingDxfSerializer.HasMetadata(fileName)){opened=VCuttingDxfSerializer.Load(fileName);status=Localization.Format("ui.0040", opened.Unit.Symbol());}else{if(MessageBox.Show(this,Localization.Text("ui.0041"),Localization.Text("ui.0042"),MessageBoxButton.OKCancel,MessageBoxImage.Question)!=MessageBoxResult.OK)return;var imported=GeneralDxfImportEngine.Import(fileName);opened=imported.Document;if(opened.Unit!=_settings.DefaultUnit)opened.ChangeUnit(_settings.DefaultUnit,UnitChangeMode.PreservePhysicalSize);ApplySectionDefaults(opened);plainImport=true;status=Localization.Format("ui.0043", opened.Unit.Symbol(), imported.OuterEntities, imported.CutObjects, imported.BendObjects);if(imported.Warnings.Count>0)MessageBox.Show(this,string.Join(Environment.NewLine,imported.Warnings),Localization.Text("ui.0044"),MessageBoxButton.OK,MessageBoxImage.Warning);}_history.Clear();Attach(opened);_path=plainImport?null:fileName;_titlePath=fileName;_dirtyState.MarkSaved();UpdateWindowTitle();StatusText.Text=status;UserSettingsStore.AddRecent(_settings,fileName);RebuildRecentMenu();}catch(Exception ex){MessageBox.Show(this,ex.Message,Localization.Text("ui.0045"),MessageBoxButton.OK,MessageBoxImage.Error);}}
    void Save_Click(object sender,RoutedEventArgs e)=>TrySaveCurrent();
    void SaveAs_Click(object sender,RoutedEventArgs e)=>TrySaveAs();
    bool TrySaveCurrent()=>_path is null?TrySaveAs():SaveTo(_path);
    bool TrySaveAs(){var d=new SaveFileDialog{Filter=Localization.DxfFilter,DefaultExt=".dxf",FileName="VCuttingDesign.dxf",InitialDirectory=ValidFolder(_settings.DefaultSaveFolder)};if(d.ShowDialog()!=true)return false;_path=d.FileName;return SaveTo(_path);}
    bool SaveTo(string path){try{SyncSectionViewState();VCuttingDxfSerializer.Save(_document,path);_titlePath=path;_dirtyState.MarkSaved();UpdateWindowTitle();StatusText.Text=Localization.Text("ui.0047");UserSettingsStore.AddRecent(_settings,path);RebuildRecentMenu();return true;}catch(Exception ex){MessageBox.Show(this,ex.Message,Localization.Text("ui.0048"),MessageBoxButton.OK,MessageBoxImage.Error);return false;}}
    void Exit_Click(object sender,RoutedEventArgs e)=>Close();
    bool ConfirmSaveChanges(){if(!_dirtyState.IsDirty)return true;var result=MessageBox.Show(this,Localization.Text("ui.0049"),Localization.Text("ui.0050"),MessageBoxButton.YesNoCancel,MessageBoxImage.Warning);return result switch{MessageBoxResult.Yes=>TrySaveCurrent(),MessageBoxResult.No=>true,_=>false};}
    void MainWindow_Closing(object? sender,System.ComponentModel.CancelEventArgs e){if(!ConfirmSaveChanges())e.Cancel=true;}
    void Thickness_LostFocus(object sender,RoutedEventArgs e)
    {
        if(!double.TryParse(ThicknessBox.Text,NumberStyles.Float,CultureInfo.CurrentCulture,out var value)||value<=0){ThicknessBox.Text=_document.Material.Thickness.ToString(CultureInfo.CurrentCulture);return;}if(Math.Abs(value-_document.Material.Thickness)<1e-9)return;
        var message=Localization.Format("ui.0051", _document.Material.Thickness, value, _document.Unit.Symbol());
        if(MessageBox.Show(this,message,Localization.Text("ui.0052"),MessageBoxButton.OKCancel,MessageBoxImage.Warning)==MessageBoxResult.OK){RecordEdit();_document.ChangeThickness(value);StatusText.Text=Localization.Text("ui.0053");}else ThicknessBox.Text=_document.Material.Thickness.ToString(CultureInfo.CurrentCulture);
    }
    void ViewOption_Click(object sender,RoutedEventArgs e){WSection.ShowDimensions=WDimensions.IsChecked==true;HSection.ShowDimensions=HDimensions.IsChecked==true;WSection.BentMode=WBent.IsChecked==true;HSection.BentMode=HBent.IsChecked==true;Preview3D.Transparent=Transparent3D.IsChecked==true;SyncSectionViewState();if(sender is Button)Preview3D.ResetView();SyncSectionMenus();WSection.Refresh();HSection.Refresh();Preview3D.Refresh();}
    void FitSection_Click(object sender,RoutedEventArgs e){if(sender is Button{Tag:"W"})WSection.FitToWindow();else if(sender is Button{Tag:"H"})HSection.FitToWindow();}
    void RotateSection_Click(object sender,RoutedEventArgs e){if(sender is Button{Tag:"W"})WSection.RotateClockwise();else if(sender is Button{Tag:"H"})HSection.RotateClockwise();SyncSectionViewState();SyncSectionMenus();StatusText.Text=Localization.Text("ui.0054");}
    void HoleTool_Click(object sender,RoutedEventArgs e){FlatView.CancelBendDrawing();FlatView.CancelSlitDrawing();var shape=(sender as Button)?.Tag as string;FlatView.FilletMode=false;if(shape=="RegularStar"&&FlatView.ActiveHoleShape!="RegularStar"){PolygonSidesBox.Text="5";StarStepBox.Text="2";}FlatView.ActiveHoleShape=shape;SelectModeButton.IsChecked=false;FlatView.Cursor=System.Windows.Input.Cursors.Cross;FlatView.Focus();FlatView.Refresh();StatusText.Text=shape is "RegularPolygon" or "RegularStar"?Localization.Text(shape=="RegularStar"?"star.instructions":"polygon.instructions"):HoleDragEngine.Supports(shape)?Localization.Format("ui.0055", Localization.DisplayKind(shape)):Localization.Format("ui.0056", Localization.DisplayKind(shape));}
    void FilletTool_Click(object sender,RoutedEventArgs e){FlatView.CancelBendDrawing();FlatView.CancelSlitDrawing();if(!double.TryParse(FilletRadiusBox.Text,NumberStyles.Float,CultureInfo.CurrentCulture,out var radius)||radius<=0){MessageBox.Show(this,Localization.Text("ui.0057"),Localization.Text("ui.0058"),MessageBoxButton.OK,MessageBoxImage.Warning);return;}FlatView.ActiveHoleShape=null;FlatView.FilletMode=true;FlatView.FilletRadius=radius;SelectModeButton.IsChecked=false;FlatView.Cursor=System.Windows.Input.Cursors.Cross;FlatView.Focus();FlatView.Refresh();StatusText.Text=Localization.Format("ui.0059", radius);}
    void BendTool_Click(object sender,RoutedEventArgs e)
    {
        var layer=(sender as Button)?.Tag as string;if(layer is not ("V" or "V1"))return;
        FlatView.BeginBendDrawing(layer);SelectModeButton.IsChecked=false;
        StatusText.Text=layer+Localization.Text("ui.0060");
    }
    void SlitTool_Click(object sender,RoutedEventArgs e)
    {
        FlatView.CancelBendDrawing();FlatView.ActiveHoleShape=null;FlatView.FilletMode=false;
        FlatView.BeginSlitDrawing((sender as Button)?.Tag as string??"Line");
        SelectModeButton.IsChecked=false;FlatView.Focus();
        StatusText.Text=FlatView.ActiveSlitShape switch{"Arc"=>Localization.Text("ui.0062"),"Polyline"=>Localization.Text("ui.0064"),_=>Localization.Text("ui.0065")};
    }
    void SlitPlacementRequested(object? sender,SlitPlacementEventArgs e)
    {
        if(!SlitDrawingEngine.Fits(e.Geometry,_document.Material.Width,_document.Material.Height))return;
        RecordEdit();var slit=_document.AddSlit(e.Shape,e.Geometry);if(slit is null)return;
        ActivateSelectMode(Localization.Format("status.slitCreated",Localization.DisplayKind(e.Shape),slit.Id));
        FlatView.SelectedObject=slit;RefreshAll();SelectTreeObject(slit.Id);ShowProperties(slit);UpdateHistoryUi();
    }
    void SelectMode_Click(object sender,RoutedEventArgs e){ActivateSelectMode(Localization.Text("status.selection"));}
    void ActivateSelectMode(string status){FlatView.CancelBendDrawing();FlatView.CancelSlitDrawing();FlatView.ActiveHoleShape=null;FlatView.FilletMode=false;SelectModeButton.IsChecked=true;FlatView.Cursor=System.Windows.Input.Cursors.Arrow;FlatView.Refresh();StatusText.Text=status;}
    void FlatHoleToolCancelled(object? sender,EventArgs e)=>ActivateSelectMode(Localization.Text("status.holeCancelled"));
    void HolePlacementRequested(object? sender,HolePlacementEventArgs e){RecordEdit();var cut=_document.AddHole(e.Shape,e.X,e.Y);if(e.Shape is "Semicircle" or "QuarterCircle"){cut.Geometry.Clear();cut.Geometry.Add(new ArcSegment(0,0,1,e.SemicircleStartDegrees,e.SemicircleStartDegrees+(e.Shape=="QuarterCircle"?90:180)));}if(e.Shape=="Triangle"&&e.TriangleVertices is {Count:3} vertices)_document.UpdateTriangleVertices(cut,vertices);else if(e.Shape=="Ellipse"&&e.ContourVertices is {Count:48})_document.ApplyEllipseContour(cut,e.ContourVertices);else _document.UpdateCut(cut,e.X,e.Y,e.Width,e.Height,cut.Sides);FlatView.SelectedObject=cut;WSection.SelectedObject=cut;HSection.SelectedObject=cut;ActivateSelectMode(Localization.Format("status.holeCreated",Localization.DisplayKind(e.Shape),cut.Id));RefreshAll();SelectTreeObject(cut.Id);ShowProperties(cut);StatusText.Text=_document.CanMergeBoundaryCut(cut)?Localization.Text("ui.0066"):_document.CanMergeInternalCuts(cut)?Localization.Text("merge.candidate"):Localization.Format("status.holeCreated",Localization.DisplayKind(e.Shape),cut.Id);}
    void InternalMergeRequested(object? sender,CutOperation cut){if(!_document.CanMergeInternalCuts(cut))return;RecordEdit();if(!_document.TryMergeInternalCuts(cut))return;FlatView.SelectedObject=cut;WSection.SelectedObject=cut;HSection.SelectedObject=cut;RefreshAll();SelectTreeObject(cut.Id);ShowProperties(cut);UpdateHistoryUi();StatusText.Text=Localization.Text("merge.completed");}
    void BoundaryMergeRequested(object? sender,CutOperation cut){if(!_document.CanMergeBoundaryCut(cut))return;RecordEdit();if(!_document.TryMergeBoundaryCut(cut))return;FlatView.SelectedObject=_document.OuterContour;WSection.SelectedObject=_document.OuterContour;HSection.SelectedObject=_document.OuterContour;RefreshAll();SelectTreeObject(_document.OuterContour.Id);ShowProperties(_document.OuterContour);StatusText.Text=Localization.Format("ui.0069", cut.Shape);}
    void OuterFilletRequested(object? sender,OuterFilletEventArgs e){RecordEdit();if(!_document.TryFilletContourCorner(e.ContourId,e.VertexIndex,e.Radius,out var arc)||arc is null){var restored=_history.Undo(_document);if(restored is not null)Attach(restored);StatusText.Text=Localization.Text("ui.0070");return;}var id=e.ContourId=="OUTER"?$"L{e.VertexIndex+1:000}":$"{e.ContourId}-L{e.VertexIndex+1:000}";var selected=new GeometryObject{Id=id,Sequence=e.VertexIndex+1,ParentContourId=e.ContourId,Layer="L",EntityType="ARC",Geometry=arc};FlatView.SelectedObject=selected;WSection.SelectedObject=selected;HSection.SelectedObject=selected;ActivateSelectMode(Localization.Format("status.filletApplied",e.ContourId=="OUTER"?Localization.Text("ui.0021"):e.ContourId,e.Radius));RefreshAll();SelectTreeObject(id);ShowProperties(selected);UpdateHistoryUi();}
    void FlatPointerChanged(object? sender,PointerPositionEventArgs e)=>PointerText.Text=e.InsideMaterial?Localization.Format("ui.0071", e.X, e.Y, _document.Unit.Symbol()):Localization.Format("ui.0072", _document.Unit.Symbol());
    void FlatSectionSelectionChanged(object? sender,SectionSelectionChangedEventArgs e){var view=e.Axis==SectionAxis.H?HSection:WSection;view.SectionPosition=e.Position;view.Refresh();StatusText.Text=Localization.Format("ui.0073", e.Axis, (e.Axis==SectionAxis.H?"X":"Y"), e.Position, _document.Unit.Symbol());}
    void FlatObjectSelected(object? sender,DesignObject e){FlatView.SelectedObject=e;WSection.SelectedObject=e;HSection.SelectedObject=e;SelectTreeObject(e.Id);ShowProperties(e);FlatView.Refresh();WSection.Refresh();HSection.Refresh();StatusText.Text=e is CutOperation cut&&_document.CanMergeBoundaryCut(cut)?Localization.Text("ui.0074"):e is CutOperation inner&&_document.CanMergeInternalCuts(inner)?Localization.Text("merge.candidate"):Localization.Format("ui.0075", e.Id);}
    void ObjectTree_SelectedItemChanged(object sender,RoutedPropertyChangedEventArgs<object> e){if(e.NewValue is not TreeViewItem{Tag:DesignObject o})return;FlatView.SelectedObject=o;WSection.SelectedObject=o;HSection.SelectedObject=o;FlatView.Refresh();WSection.Refresh();HSection.Refresh();ShowProperties(o);StatusText.Text=Localization.Format("ui.0076", o.Id);}
    void ShowProperties(DesignObject o)
    {
        PropertyPanel.Children.Clear();ReadOnlyRow(Localization.Text("ui.0077"),o.Id);
        if(o is MaterialModel m){var u=_document.Unit.Symbol();ReadOnlyRow(Localization.Format("ui.0078", u),m.Width);ReadOnlyRow(Localization.Format("ui.0079", u),m.Height);EditNumber(Localization.Format("ui.0080", u),m.Thickness,v=>{if(v<=0)return;var message=Localization.Format("ui.0081", m.Thickness, u, v, u);if(MessageBox.Show(this,message,Localization.Text("ui.0082"),MessageBoxButton.OKCancel,MessageBoxImage.Warning)==MessageBoxResult.OK){RecordEdit();_document.ChangeThickness(v);}});}
        else if(o is BendObject b){ReadOnlyRow(Localization.Text("ui.0083"),b.Axis);EditChoice("Direction",b.Direction,Enum.GetValues<BendDirection>(),v=>{RecordEdit();_document.UpdateBend(b,b.Position,v,b.Sequence);});EditNumber(b.Axis==SectionAxis.W?Localization.Format("ui.0084", _document.Unit.Symbol()):Localization.Format("ui.0085", _document.Unit.Symbol()),b.Position,v=>{RecordEdit();_document.UpdateBend(b,v,b.Direction,b.Sequence);});ReadOnlyRow(Localization.Text("ui.0086"),b.BendAngle);ReadOnlyRow(Localization.Text("ui.0087"),b.VCutAngle);ReadOnlyRow(Localization.Format("ui.0088", _document.Unit.Symbol()),b.VCutDepth);ReadOnlyRow(Localization.Format("ui.0089", _document.Unit.Symbol()),b.ResidualThickness);EditNumber(Localization.Text("ui.0090"),b.Sequence,v=>{RecordEdit();_document.UpdateBend(b,b.Position,b.Direction,(int)v);});}
        else if(o is SectionSegment s){ReadOnlyRow(Localization.Text("ui.0091"),s.Axis);EditNumber(Localization.Format("ui.0092", _document.Unit.Symbol()),s.Length,v=>{RecordEdit();_document.UpdateSegment(s,v);});}
        else if(o is GeometryObject g){ReadOnlyRow(Localization.Text("ui.0093"),g.Layer);ReadOnlyRow(Localization.Text("ui.0094"),g.EntityType);if(g.ParentContourId!="OUTER")ReadOnlyRow(Localization.Text("ui.0095"),g.ParentContourId);if(g.Geometry is LineSegment l){ReadOnlyRow(Localization.Text("ui.0096"),l.X1);ReadOnlyRow(Localization.Text("ui.0097"),l.Y1);ReadOnlyRow(Localization.Text("ui.0098"),l.X2);ReadOnlyRow(Localization.Text("ui.0099"),l.Y2);}else if(g.Geometry is ArcSegment arc){ShowArcAngles(g.ParentContourId,arc,g);EditNumber(Localization.Format("ui.0100", _document.Unit.Symbol()),arc.Radius,v=>{if(v<=0)return;RecordEdit();if(!_document.TryResizeFillet(g.ParentContourId,arc,v,out var updated)||updated is null){var restored=_history.Undo(_document);if(restored is not null)Attach(restored);StatusText.Text=Localization.Text("ui.0101");return;}var selected=new GeometryObject{Id=g.Id,Sequence=g.Sequence,ParentContourId=g.ParentContourId,Layer="L",EntityType="ARC",Geometry=updated};FlatView.SelectedObject=selected;WSection.SelectedObject=selected;HSection.SelectedObject=selected;RefreshAll();SelectTreeObject(g.Id);ShowProperties(selected);UpdateHistoryUi();});ReadOnlyRow(Localization.Text("ui.0102"),arc.Cx);ReadOnlyRow(Localization.Text("ui.0103"),arc.Cy);}}
        else if(o is SlitOperation slit){ReadOnlyRow(Localization.Text("ui.0104"),"L");ReadOnlyRow(Localization.Text("ui.0105"),Localization.Kind(slit.Shape));ReadOnlyRow(Localization.Text("ui.0106"),slit.Geometry.Count);var u=_document.Unit.Symbol();foreach(var segment in slit.Geometry){if(segment is LineSegment line){ReadOnlyRow(Localization.Format("ui.0107", u),$"{line.X1:0.###}, {line.Y1:0.###}");ReadOnlyRow(Localization.Format("ui.0108", u),$"{line.X2:0.###}, {line.Y2:0.###}");}else if(segment is ArcSegment a){ReadOnlyRow(Localization.Format("ui.0109", u),$"{a.Cx:0.###}, {a.Cy:0.###}");ReadOnlyRow(Localization.Format("ui.0110", u),a.Radius);ShowArcAngles(slit.Id,a,slit);}}}
        else if(o is CutOperation c){ReadOnlyRow(Localization.Text("ui.0112"),"L");ReadOnlyRow(Localization.Text("ui.0113"),Localization.Kind(c.Shape));if(RotatedRectangleGeometry.IsParametric(c)){ShowRectangleProperties(c);return;}if(c.Shape=="RegularStar"){ShowRegularStarProperties(c);return;}if(c.Shape=="RegularPolygon"){ShowRegularPolygonProperties(c);return;}if(c.Shape=="Compound"){ShowCompoundProperties(c);return;}if(EllipsePropertiesEngine.TryGet(c,out var ellipse)){ShowEllipseProperties(c,ellipse);return;}if(c.QuarterCircleArc is ArcSegment quarter){var unit=_document.Unit.Symbol();EditNumber(Localization.Format("ui.0114", unit),quarter.Cx,v=>EditQuarterCircleProperty(c,v,c.QuarterCircleArc!.Cy,c.QuarterCircleArc.Radius));EditNumber(Localization.Format("ui.0115", unit),quarter.Cy,v=>EditQuarterCircleProperty(c,c.QuarterCircleArc!.Cx,v,c.QuarterCircleArc.Radius));EditNumber(Localization.Format("ui.0116", unit),quarter.Radius,v=>EditQuarterCircleProperty(c,c.QuarterCircleArc!.Cx,c.QuarterCircleArc.Cy,v));return;}if(c.SemicircleArc is ArcSegment semicircle){var unit=_document.Unit.Symbol();EditNumber(Localization.Format("ui.0117", unit),semicircle.Cx,v=>EditSemicircleProperty(c,v,c.SemicircleArc!.Cy,c.SemicircleArc.Radius));EditNumber(Localization.Format("ui.0118", unit),semicircle.Cy,v=>EditSemicircleProperty(c,c.SemicircleArc!.Cx,v,c.SemicircleArc.Radius));EditNumber(Localization.Format("ui.0119", unit),semicircle.Radius,v=>EditSemicircleProperty(c,c.SemicircleArc!.Cx,c.SemicircleArc.Cy,v));return;}if(c.Shape=="Triangle"){var unit=_document.Unit.Symbol();EditNumber(Localization.Format("ui.0120", unit),c.LowerLeftX,v=>{if(!double.IsFinite(v)||Math.Abs(v-c.LowerLeftX)<.0005)return;RecordEdit();_document.MoveTriangleLowerLeft(c,v,c.LowerLeftY);ShowProperties(c);});EditNumber(Localization.Format("ui.0121", unit),c.LowerLeftY,v=>{if(!double.IsFinite(v)||Math.Abs(v-c.LowerLeftY)<.0005)return;RecordEdit();_document.MoveTriangleLowerLeft(c,c.LowerLeftX,v);ShowProperties(c);});}else{EditNumber(Localization.Format("ui.0122", _document.Unit.Symbol()),c.CenterX,v=>{RecordEdit();_document.UpdateCut(c,v,c.CenterY,c.Width,c.Height,c.Sides);});EditNumber(Localization.Format("ui.0123", _document.Unit.Symbol()),c.CenterY,v=>{RecordEdit();_document.UpdateCut(c,c.CenterX,v,c.Width,c.Height,c.Sides);});}if(c.Shape=="Circle"){EditNumber(Localization.Format("ui.0124", _document.Unit.Symbol()),c.Width/2,v=>{if(Math.Abs(v-c.Width/2)<.0005)return;if(!_document.CanResizeCircleRadius(c,v)){ShowProperties(c);Dispatcher.BeginInvoke(()=>StatusText.Text=Localization.Text("ui.0125"));return;}RecordEdit();_document.TryResizeCircleRadius(c,v);ShowProperties(c);});}else{EditNumber(Localization.Format("ui.0126", _document.Unit.Symbol()),c.Width,v=>{if(c.Shape=="Triangle"){ResizeTriangleProperty(c,v,c.Height);return;}RecordEdit();_document.UpdateCut(c,c.CenterX,c.CenterY,v,c.Height,c.Sides);});EditNumber(Localization.Format("ui.0127", _document.Unit.Symbol()),c.Height,v=>{if(c.Shape=="Triangle"){ResizeTriangleProperty(c,c.Width,v);return;}RecordEdit();_document.UpdateCut(c,c.CenterX,c.CenterY,c.Width,v,c.Sides);});}if(c.Shape=="Polygon")EditNumber(Localization.Text("ui.0128"),c.Sides,v=>{RecordEdit();_document.UpdateCut(c,c.CenterX,c.CenterY,c.Width,c.Height,(int)v);});}
