    void EditQuarterCircleProperty(CutOperation cut,double x,double y,double radius)
    {
        if(cut.QuarterCircleArc is not ArcSegment arc)return;
        if(Math.Abs(x-arc.Cx)+Math.Abs(y-arc.Cy)+Math.Abs(radius-arc.Radius)<.0005)return;
        if(!_document.CanUpdateQuarterCircle(cut,x,y,radius)){ShowProperties(cut);Dispatcher.BeginInvoke(()=>StatusText.Text=Localization.Text("ui.0132"));return;}
        RecordEdit();_document.TryUpdateQuarterCircle(cut,x,y,radius);ShowProperties(cut);
    }
    void ShowCompoundProperties(CutOperation cut)
    {
        var unit=_document.Unit.Symbol();
        EditEllipseNumber(Localization.Format("ellipse.centerX",unit),cut.CenterX,v=>EditCompoundProperty(cut,v,cut.CenterY,cut.Width,cut.Height));
        EditEllipseNumber(Localization.Format("ellipse.centerY",unit),cut.CenterY,v=>EditCompoundProperty(cut,cut.CenterX,v,cut.Width,cut.Height));
        if(cut.Geometry.Any(g=>g is ArcSegment)){
            ReadOnlyRow(Localization.Format("ui.0126",unit),cut.Width);ReadOnlyRow(Localization.Format("ui.0127",unit),cut.Height);
            EditEllipseNumber(Localization.Text("merge.scale"),100,v=>EditCompoundProperty(cut,cut.CenterX,cut.CenterY,cut.Width*v/100,cut.Height*v/100));
        }else{
            EditEllipseNumber(Localization.Format("ui.0126",unit),cut.Width,v=>EditCompoundProperty(cut,cut.CenterX,cut.CenterY,v,cut.Height));
            EditEllipseNumber(Localization.Format("ui.0127",unit),cut.Height,v=>EditCompoundProperty(cut,cut.CenterX,cut.CenterY,cut.Width,v));
        }
        ReadOnlyRow(Localization.Text("merge.loops"),CutContourEngine.Loops(cut.Geometry).Count);
    }
    void EditCompoundProperty(CutOperation cut,double x,double y,double width,double height)
    {
        if(!_document.CanUpdateCompound(cut,x,y,width,height)){ShowProperties(cut);Dispatcher.BeginInvoke(()=>StatusText.Text=Localization.Text("merge.invalid"));return;}
        if(Math.Abs(x-cut.CenterX)<1e-9&&Math.Abs(y-cut.CenterY)<1e-9&&Math.Abs(width-cut.Width)<1e-9&&Math.Abs(height-cut.Height)<1e-9)return;
        RecordEdit();_document.TryUpdateCompound(cut,x,y,width,height);ShowProperties(cut);
    }
    void ShowEllipseProperties(CutOperation cut,EllipseProperties value)
    {
        var unit=_document.Unit.Symbol();
        EditEllipseNumber(Localization.Format("ellipse.centerX",unit),value.CenterX,v=>EditEllipseProperty(cut,p=>p with {CenterX=v}));
        EditEllipseNumber(Localization.Format("ellipse.centerY",unit),value.CenterY,v=>EditEllipseProperty(cut,p=>p with {CenterY=v}));
        EditEllipseNumber(Localization.Format("ellipse.major",unit),value.MajorLength,v=>EditEllipseProperty(cut,p=>p with {MajorLength=v}));
        EditEllipseNumber(Localization.Format("ellipse.minor",unit),value.MinorLength,v=>EditEllipseProperty(cut,p=>p with {MinorLength=v}));
        EditEllipseNumber(Localization.Text("ellipse.angle"),value.RotationDegrees,v=>EditEllipseProperty(cut,p=>p with {RotationDegrees=v}));
        ReadOnlyRow(Localization.Text("ellipse.ratio"),(value.MinorLength/value.MajorLength).ToString("0.###",CultureInfo.CurrentCulture));
    }
    void EditEllipseNumber(string name,double value,Action<double> apply,string invalidKey="ellipse.invalid")
    {
        var original=value.ToString("0.###",CultureInfo.CurrentCulture);
        var box=new TextBox{Text=original};
        box.LostFocus+=(_,_)=>{
            if(box.Text==original)return;
            if(!double.TryParse(box.Text,NumberStyles.Float,CultureInfo.CurrentCulture,out var v)||!double.IsFinite(v)){box.Text=original;StatusText.Text=Localization.Text(invalidKey);return;}
            StatusText.Text=Localization.Format("ui.0135",name);apply(v);
        };
        AddRow(name,box);
    }
    void EditEllipseProperty(CutOperation cut,Func<EllipseProperties,EllipseProperties> change)
    {
        if(!EllipsePropertiesEngine.TryGet(cut,out var old))return;
        var target=change(old);if(double.IsFinite(target.RotationDegrees))target=target with {RotationDegrees=EllipseProperties.NormalizeAngle(target.RotationDegrees)};
        if(!_document.CanUpdateEllipse(cut,target)){ShowProperties(cut);Dispatcher.BeginInvoke(()=>StatusText.Text=Localization.Text("ellipse.invalid"));return;}
        if(Math.Abs(old.CenterX-target.CenterX)<1e-9&&Math.Abs(old.CenterY-target.CenterY)<1e-9&&Math.Abs(old.MajorLength-target.MajorLength)<1e-9&&Math.Abs(old.MinorLength-target.MinorLength)<1e-9&&Math.Abs(old.RotationDegrees-target.RotationDegrees)<1e-9)return;
        RecordEdit();_document.TryUpdateEllipse(cut,target);ShowProperties(cut);
    }
    void EditSemicircleProperty(CutOperation cut,double x,double y,double radius)
    {
        if(cut.SemicircleArc is not ArcSegment arc)return;
        if(Math.Abs(x-arc.Cx)<.0005&&Math.Abs(y-arc.Cy)<.0005&&Math.Abs(radius-arc.Radius)<.0005)return;
        if(!_document.CanUpdateSemicircle(cut,x,y,radius)){ShowProperties(cut);Dispatcher.BeginInvoke(()=>StatusText.Text=Localization.Text("ui.0133"));return;}
        RecordEdit();_document.TryUpdateSemicircle(cut,x,y,radius);ShowProperties(cut);
    }
    void ResizeTriangleProperty(CutOperation cut,double width,double height)
    {
        if(Math.Abs(width-cut.Width)<.0005&&Math.Abs(height-cut.Height)<.0005)return;
        if(!double.IsFinite(width)||!double.IsFinite(height)||width<.1||height<.1||cut.LowerLeftX+width>_document.Material.Width||cut.LowerLeftY+height>_document.Material.Height||cut.Geometry.Count!=3||cut.Geometry.Any(g=>g is not LineSegment))
        {
            ShowProperties(cut);
            Dispatcher.BeginInvoke(()=>StatusText.Text=Localization.Text("ui.0134"));
            return;
        }
        RecordEdit();
        _document.TryResizeTriangleLowerLeft(cut,width,height);
        ShowProperties(cut);
    }
    void ReadOnlyRow(string name,object value)=>AddRow(name,new TextBox{Text=Convert.ToString(value,CultureInfo.CurrentCulture),IsReadOnly=true,Background=System.Windows.Media.Brushes.Gainsboro});
    void EditNumber(string name,double value,Action<double> apply){var box=new TextBox{Text=value.ToString("0.###",CultureInfo.CurrentCulture)};box.LostFocus+=(_,_)=>{if(double.TryParse(box.Text,NumberStyles.Float,CultureInfo.CurrentCulture,out var v)){apply(v);StatusText.Text=Localization.Format("ui.0135", name);}else{box.Text=value.ToString(CultureInfo.CurrentCulture);StatusText.Text=Localization.Format("ui.0136", name);}};AddRow(name,box);}
    void EditChoice<T>(string name,T value,IEnumerable<T> values,Action<T> apply){var box=new ComboBox{ItemsSource=values,SelectedItem=value};box.SelectionChanged+=(_,_)=>{if(box.SelectedItem is T v)apply(v);};AddRow(name,box);}
    void AddRow(string name,Control editor){var grid=new Grid{Margin=new Thickness(0,2,0,2)};grid.ColumnDefinitions.Add(new ColumnDefinition());grid.ColumnDefinitions.Add(new ColumnDefinition{Width=new GridLength(112)});grid.Children.Add(new TextBlock{Text=name,VerticalAlignment=VerticalAlignment.Center});Grid.SetColumn(editor,1);grid.Children.Add(editor);PropertyPanel.Children.Add(grid);}
    void Undo_Click(object sender,RoutedEventArgs e){var restored=_history.Undo(_document);if(restored is null)return;Attach(restored);_dirtyState.MarkChanged();UpdateWindowTitle();StatusText.Text=Localization.Text("ui.0137");UpdateHistoryUi();}
    void Redo_Click(object sender,RoutedEventArgs e){var restored=_history.Redo(_document);if(restored is null)return;Attach(restored);_dirtyState.MarkChanged();UpdateWindowTitle();StatusText.Text=Localization.Text("ui.0138");UpdateHistoryUi();}
    void MainWindow_PreviewKeyDown(object sender,System.Windows.Input.KeyEventArgs e){if(HandleShapeClipboard(e)){e.Handled=true;return;}if(FlatView.HandleRegularPolygonKey(e.Key)||FlatView.HandleBendKey(e.Key)||FlatView.HandleSlitKey(e.Key)){e.Handled=true;return;}if(e.Key==System.Windows.Input.Key.Delete&&(ObjectTree.IsKeyboardFocusWithin||FlatView.IsKeyboardFocusWithin)){DeleteSelectedObject(FlatView.IsKeyboardFocusWithin?FlatView.SelectedObject:null);e.Handled=true;return;}var fileAction=FileShortcutEngine.Resolve(e.Key,System.Windows.Input.Keyboard.Modifiers);if(fileAction!=FileShortcutAction.None){if(fileAction==FileShortcutAction.New)New_Click(sender,e);else if(fileAction==FileShortcutAction.Open)Open_Click(sender,e);else Save_Click(sender,e);e.Handled=true;return;}if(System.Windows.Input.Keyboard.Modifiers!=System.Windows.Input.ModifierKeys.Control)return;if(e.Key==System.Windows.Input.Key.Z){Undo_Click(sender,e);e.Handled=true;}else if(e.Key==System.Windows.Input.Key.Y){Redo_Click(sender,e);e.Handled=true;}else if(e.Key==System.Windows.Input.Key.OemComma){Settings_Click(sender,e);e.Handled=true;}}
    void DeleteSelectedObject(DesignObject? requested=null){var selected=requested??(ObjectTree.SelectedItem as TreeViewItem)?.Tag as DesignObject;if(selected is null)return;if(selected is MaterialModel or ContourObject or SectionSegment){StatusText.Text=Localization.Text("ui.0139");return;}RecordEdit();if(!_document.DeleteObject(selected)){var restored=_history.Undo(_document);if(restored is not null)Attach(restored);StatusText.Text=Localization.Text("ui.0140");return;}PropertyPanel.Children.Clear();FlatView.SelectedObject=null;WSection.SelectedObject=null;HSection.SelectedObject=null;StatusText.Text=Localization.Format("ui.0141", selected.Id);RefreshAll();UpdateHistoryUi();}
    void Help_Click(object sender,RoutedEventArgs e)=>UserHelp.Open(this,(sender as MenuItem)?.Tag as string??"index.html");
    void About_Click(object sender,RoutedEventArgs e)=>MessageBox.Show(this,Localization.About(),Localization.Text("ui.0143"),MessageBoxButton.OK,MessageBoxImage.Information);
